def conservar_personal_existente(apps, schema_editor):
    Usuario = apps.get_model(settings.AUTH_USER_MODEL)
    Trabajador = apps.get_model('asistencia', 'Trabajador')
    Identidad = apps.get_model('asistencia', 'IdentidadBiometrica')
    alias = schema_editor.connection.alias
    for usuario in Usuario.objects.using(alias).all():
        if len(usuario.dni) != 8 or not usuario.dni.isascii() or not usuario.dni.isdigit():
            continue
        nombre = f'{usuario.first_name} {usuario.last_name}'.strip() or usuario.username
        ficha, _ = Trabajador.objects.using(alias).get_or_create(dni=usuario.dni, defaults={
            'nombre_completo': nombre[:150], 'area': 'Por completar',
            'sede': usuario.agencia_sede, 'usuario_id': usuario.pk,
        })
        Identidad.objects.using(alias).filter(usuario_id=usuario.pk).update(trabajador_id=ficha.pk)


